const std = @import("std");

const User = struct {
    id: u32,
    name: []const u8,
    age: u8,
};

fn inspect(comptime T: type) void {
    const fields = @typeInfo(T).Struct.fields;
    inline for (fields) |field| {
        std.debug.print("{s}: {s}\n", .{field.name, @typeName(field.field_type)});
    }
}

pub fn main() !void {
    inspect(User);
}
